module adder_16bit (
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);

wire carry; // Only the 0th bit of carry is used, so we can reduce the size to 1 bit

adder_8bit adder_low (.a(a[7:0]), .b(b[7:0]), .cin(Cin), .y(y[7:0]), .cout(carry));
adder_8bit adder_high (.a(a[15:8]), .b(b[15:8]), .cin(carry), .y(y[15:8]), .cout(Co));

endmodule
module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

assign sum = a ^ b ^ cin;
assign cout = (a & b) | (cin & (a ^ b));

endmodule

